/**
 * next/image custom loader (works with static export).
 * - Local photos ("/images/<key>"): pick the pre-built AVIF width that covers the request
 *   (files are generated by scripts/build-images.mjs — keep WIDTHS in sync).
 * - Unsplash URLs (if you ever reference one directly): resized, auto-format from their CDN.
 * - Anything else: returned as-is.
 */
const WIDTHS = [384, 640, 960, 1280, 1920];

export default function imageLoader({ src, width, quality }: { src: string; width: number; quality?: number }) {
  if (src.startsWith("/images/") && !/\.\w+$/.test(src)) {
    const w = WIDTHS.find((x) => x >= width) ?? WIDTHS[WIDTHS.length - 1];
    return `${src}-${w}.avif`;
  }
  if (src.startsWith("https://images.unsplash.com/")) {
    const url = new URL(src);
    url.searchParams.set("w", String(width));
    url.searchParams.set("q", String(quality || 70));
    url.searchParams.set("auto", "format");
    url.searchParams.set("fit", "crop");
    return url.toString();
  }
  return src;
}
